class Name(str):
 def __str__(self): raise RuntimeError('str called')
 def __hash__(self): raise RuntimeError('hash called')
 def __eq__(self, other): raise RuntimeError('eq called')
class Meta(type):
 def __setattr__(self, name, value): raise RuntimeError('override set')
 def __delattr__(self, name): raise RuntimeError('override del')
class C(metaclass=Meta): pass
result = []
for target in [C, int]:
 try:
  r = type.__setattr__(target, Name('absent'), 37)
  result.append(('ok', r))
 except Exception as e:
  result.append((type(e).__name__, str(e)))

